namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int CeilingRatePoints = 10;

    public static int DiscountCentsFor(LoyaltyTier tier, int subtotalCents)
    {
        var ratePoints = BaseRatePointsFor(tier) + OrderSizeBonusPointsFor(subtotalCents);
        if (ratePoints > CeilingRatePoints)
        {
            ratePoints = CeilingRatePoints;
        }

        return subtotalCents * ratePoints / 100;
    }

    private static int BaseRatePointsFor(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, message: null)
    };

    private static int OrderSizeBonusPointsFor(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
EOF

